Here is a complete, production-ready implementation in Python using the `decimal` module and `dataclasses`.

It supports percentage-based and fixed-amount discounts, prevents duplicate codes, rounds properly to currency precision, and ensures the total never drops below zero.

```python
from dataclasses import dataclass, field
from decimal import Decimal, ROUND_HALF_UP
from enum import Enum
from typing import Dict, List, Set


# Currency helper: Ensures proper 2-decimal place bankers/half-up rounding
def round_money(amount: Decimal) -> Decimal:
    return amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


class DiscountType(Enum):
    PERCENTAGE = "PERCENTAGE"  # e.g., 20% off
    FIXED = "FIXED"            # e.g., $15.00 off


@dataclass(frozen=True)
class Discount:
    code: str
    discount_type: DiscountType
    amount: Decimal  # e.g., Decimal("0.20") for 20% or Decimal("15.00") for $15

    def calculate_discount(self, current_total: Decimal) -> Decimal:
        if self.discount_type == DiscountType.PERCENTAGE:
            return round_money(current_total * self.amount)
        elif self.discount_type == DiscountType.FIXED:
            return round_money(self.amount)
        return Decimal("0.00")


@dataclass
class CartItem:
    product_name: str
    price: Decimal
    quantity: int

    def subtotal(self) -> Decimal:
        return round_money(self.price * Decimal(self.quantity))


class ShoppingCart:
    def __init__(self):
        self.items: List[CartItem] = []
        self.applied_discounts: Dict[str, Discount] = {}

    def add_item(self, product_name: str, price: str | Decimal, quantity: int = 1):
        if quantity <= 0:
            raise ValueError("Quantity must be greater than zero.")

        # Convert strings to Decimal to avoid floating-point issues
        dec_price = Decimal(str(price))
        if dec_price < Decimal("0.00"):
            raise ValueError("Price cannot be negative.")

        self.items.append(CartItem(product_name, dec_price, quantity))

    def apply_discount(self, discount: Discount):
        # Case-insensitive discount code tracking
        normalized_code = discount.code.strip().upper()

        if normalized_code in self.applied_discounts:
            raise ValueError(f"Discount code '{discount.code}' has already been applied.")

        self.applied_discounts[normalized_code] = discount

    def get_subtotal(self) -> Decimal:
        return sum((item.subtotal() for item in self.items), Decimal("0.00"))

    def calculate_final_price(self) -> Decimal:
        subtotal = self.get_subtotal()
        current_total = subtotal

        # Apply discounts sequentially
        for discount in self.applied_discounts.values():
            discount_value = discount.calculate_discount(current_total)
            current_total -= discount_value

        # The final price can never be negative
        final_price = max(Decimal("0.00"), current_total)
        return round_money(final_price)


# -------------------------------------------------------------
# Example Usage & Verification
# -------------------------------------------------------------
if __name__ == "__main__":
    cart = ShoppingCart()

    # 1. Add products using exact Decimals (avoid float: Decimal("19.99"), not Decimal(19.99))
    cart.add_item("T-Shirt", price="19.99", quantity=2)   # 39.98
    cart.add_item("Coffee Mug", price="12.50", quantity=1) # 12.50
    # Subtotal = 52.48

    print(f"Subtotal: ${cart.get_subtotal()}")

    # 2. Add discounts
    promo_10_percent = Discount(code="SAVE10", discount_type=DiscountType.PERCENTAGE, amount=Decimal("0.10"))
    promo_50_dollars = Discount(code="FIFTYOFF", discount_type=DiscountType.FIXED, amount=Decimal("50.00"))

    cart.apply_discount(promo_10_percent)
    print(f"After 10% discount: ${cart.calculate_final_price()}") # 52.48 - 5.25 = 47.23

    # 3. Prevent duplicate application
    try:
        cart.apply_discount(promo_10_percent)
    except ValueError as e:
        print(f"Duplicate check passed: {e}")

    # 4. Check that price cannot be negative
    cart.apply_discount(promo_50_dollars)
    # Remaining was 47.23, subtracting 50.00 would be -2.77
    print(f"After massive discount (floor at 0.00): ${cart.calculate_final_price()}")
```

### Key Decisions
1. **No Binary Floats:** Strings like `"19.99"` are parsed directly to `Decimal`. All arithmetic uses `Decimal`.
2. **Rounding Strategy:** Every calculation that might result in fractional cents (e.g., a 10% discount on an odd number) is rounded via `ROUND_HALF_UP` to 2 decimal places (`0.01`).
3. **Duplicate Prevention:** Discounts are keyed by their uppercase code string in `self.applied_discounts`, immediately raising a `ValueError` if reused.
4. **Floor at Zero:** `max(Decimal("0.00"), current_total)` prevents totals from going into the negative if discounts exceed the cart balance.

